let slider;
let phase = 0;
let zoff = 0;
let angle =0;
var seed = Math.random() * 1000;
let colors0 = "8a77b7BF-181a2140-e7e9f4BF-f16034b3-6e8fd380".split("-").map((a) => "#" + a);
let colors1 = "e3d7a3BF-f5989d33-ea618e40-fce4d6b3-caac7180".split("-").map((a) => "#" + a);
let colors2 = "6cbbd4BF-5863b140-5282a1BF-fee8f733-c1f29b80".split("-").map((a) => "#" + a);
let colors3 = "1b1b1bBF-29292940-f3f3f3BF-222222b3-ff000080".split("-").map((a) => "#" + a);
let colors4 = "70c1b3BF-aaf0d340-50514f33-ffe066b3-247ba080".split("-").map((a) => "#" + a);
let colors5 = "3c1642BF-38637540-08637533-b2ff9eb3-1dd3b080".split("-").map((a) => "#" + a);
let colorbg = "fff9e4".split("-").map((a) => "#" + a);
let colorbg2 = "fff9e403".split("-").map((a) => "#" + a);
var noiseMax;
var mySize;
var color_setup;

function setup() {
	// randomSeed(seed);
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  background(colorbg);
	noiseMax = 5;
	color_setup = random([colors0,colors1,colors2,colors3,colors4,colors5]);
	let filter = new makeFilter();
}

function draw() {
	let color_c = random(color_setup);
	// randomSeed(seed);
  // background(colorbg2);
	push();
  translate(width / 2, height / 2);
	rotate(angle);
  noFill();
  for (var i = 0; i < 20; i += 0.1) {
	  strokeWeight(random(350,500));
    stroke(color_c);
    beginShape();
    for (var a = 0; a < TWO_PI; a += (PI/3)*0.25) {
      let xoff = map(cos(a + phase), -1, 1, 0, noiseMax);
      let yoff = map(sin(a + phase / 2), -1, 1, 0, noiseMax);
      let r = map(noise(xoff, yoff, zoff), 0, 1, 0, 2000);
      let x = r * cos(a);
      let y = r * sin(a);
      vertex(x, y);
    }
    endShape(CLOSE);

  }
	pop();
	phase += 0.01;
  zoff += 0.01;
	angle += TAU / 60 / random(100, 500);
  // image(overAllTexture, 0, 0);
}

function makeFilter() {
	randomSeed(seed);
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 10);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(46, 30, 90, noise(i / 3, j / 3, (i * j) / 10) * random(1))
			);
		}
	}
	overAllTexture.updatePixels();
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("NoiseWaves_06", "png");
	}
}

